do $preflight$
begin
  raise exception 'stop: this script is not final -- migration 20261011130000 (sofascore_player_auto_map, Lane B) has not been added to it yet; nothing was saved';
  raise exception 'stop: this script is not final -- migration 20261011140000 ((Lane A migration, name to be set), Lane A) has not been added to it yet; nothing was saved';
  raise exception 'stop: this script is not final -- the md5 pin sofascoreFantasyObservation has not been filled from CI yet; nothing was saved';
